cat > migrations/002_payment_webhooks.sql <<'EOF'
-- Processed webhook events, for deduplication (the provider retries deliveries).
create table payment_webhook_events (
  id text primary key,
  received_at timestamptz not null default now()
);

-- Timestamp (provider `created`) of the last webhook that changed the order status; used to ignore stale, out-of-order events.
alter table orders add column payment_event_at timestamptz;
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
s=s.replace('import { pool } from "./db.ts";','import { createHmac, timingSafeEqual } from "node:crypto";\nimport { pool } from "./db.ts";\nimport { webhookSecret } from "./payments.ts";',1)
s=s.replace('''export function createApp() {
  const app = express();
  app.use(express.json());
''','''const eventStatus: Record<string, string> = {
  "charge.succeeded": "paid",
  "charge.failed": "failed",
  "charge.refunded": "refunded",
};
// Used to break ties between events with the same `created` second: later lifecycle stages win.
const statusRank: Record<string, number> = { pending: 0, failed: 1, paid: 1, refunded: 2 };

function validSignature(rawBody: Buffer, header: string | undefined) {
  if (!header) return false;
  const expected = createHmac("sha256", webhookSecret).update(rawBody).digest();
  const given = Buffer.from(header.trim(), "hex");
  return given.length === expected.length && timingSafeEqual(given, expected);
}

export function createApp() {
  const app = express();

  // Unauthenticated (signed by the provider); needs the raw body for signature verification.
  app.post("/webhooks/payments", express.raw({ type: () => true, limit: "100kb" }), async (req, res) => {
    const raw = Buffer.isBuffer(req.body) ? req.body : Buffer.alloc(0);
    if (!validSignature(raw, req.get("provider-signature"))) {
      return sendError(res, 401, "invalid_signature", "Invalid webhook signature");
    }
    let event: { id?: unknown; type?: unknown; paymentId?: unknown; created?: unknown };
    try {
      event = JSON.parse(raw.toString("utf8"));
    } catch {
      return sendError(res, 400, "bad_request", "Invalid JSON");
    }
    const { id, type, paymentId, created } = event;
    if (typeof id !== "string" || typeof type !== "string" || typeof paymentId !== "string" || typeof created !== "number" || !Number.isFinite(created)) {
      return sendError(res, 400, "bad_request", "Invalid event");
    }
    const status = eventStatus[type];
    if (!status) return res.json({ ok: true, ignored: true }); // unknown event types: acknowledge so they aren't retried

    const client = await pool.connect();
    try {
      await client.query("begin");
      const inserted = await client.query("insert into payment_webhook_events (id) values ($1) on conflict do nothing", [id]);
      if (inserted.rowCount === 0) {
        await client.query("rollback");
        return res.json({ ok: true, duplicate: true });
      }
      const order = await client.query("select id, status, payment_event_at from orders where payment_id = $1 for update", [paymentId]);
      if (order.rows.length === 0) {
        // Not (yet) known: don't record the event, and return an error so the provider retries.
        await client.query("rollback");
        return sendError(res, 404, "not_found", "Unknown payment");
      }
      const { id: orderId, status: current, payment_event_at: lastAt } = order.rows[0];
      const lastSec = lastAt ? Math.floor(new Date(lastAt).getTime() / 1000) : null;
      const newer = lastSec === null || created > lastSec || (created === lastSec && statusRank[status] > (statusRank[current] ?? 0));
      if (newer && current !== "refunded") {
        await client.query("update orders set status = $1, payment_event_at = to_timestamp($2) where id = $3", [status, created, orderId]);
      }
      await client.query("commit");
      res.json({ ok: true });
    } catch (err) {
      await client.query("rollback").catch(() => {});
      console.error(err);
      sendError(res, 500, "internal", "Something went wrong");
    } finally {
      client.release();
    }
  });

  app.use(express.json());
''',1)
open(p,'w').write(s)
EOF
grep -n "payment_id" db/seed.sql | head; sed -n 60,200p test/app.test.ts | head -50

cat >> test/app.test.ts <<'EOF'

async function webhook(event: object, secret = webhookSecret) {
  const body = JSON.stringify(event);
  const signature = createHmac("sha256", secret).update(body).digest("hex");
  return fetch(`${base}/webhooks/payments`, { method: "POST", headers: { "content-type": "application/json", "provider-signature": signature }, body });
}
const orderStatus = async (paymentId: string) =>
  (await pool.query("select status from orders where payment_id = $1", [paymentId])).rows[0].status;

test("webhook rejects bad signatures", async () => {
  const res = await webhook({ id: "evt_bad", type: "charge.failed", paymentId: "pay_seed_1", created: 1762300000 }, "wrong");
  assert.equal(res.status, 401);
  assert.equal(await orderStatus("pay_seed_1"), "paid");
});

test("webhook updates status, is idempotent, and ignores stale events", async () => {
  const pay = "pay_seed_2";
  assert.equal((await webhook({ id: "evt_a", type: "charge.failed", paymentId: pay, created: 1762300100 })).status, 200);
  assert.equal(await orderStatus(pay), "failed");
  // stale event delivered late
  await webhook({ id: "evt_b", type: "charge.succeeded", paymentId: pay, created: 1762300000 });
  assert.equal(await orderStatus(pay), "failed");
  await webhook({ id: "evt_c", type: "charge.succeeded", paymentId: pay, created: 1762300200 });
  assert.equal(await orderStatus(pay), "paid");
  await webhook({ id: "evt_d", type: "charge.refunded", paymentId: pay, created: 1762300300 });
  assert.equal(await orderStatus(pay), "refunded");
  // duplicate / replay of an older event must not change anything
  await webhook({ id: "evt_c", type: "charge.succeeded", paymentId: pay, created: 1762300200 });
  assert.equal(await orderStatus(pay), "refunded");
  assert.equal((await webhook({ id: "evt_e", type: "charge.succeeded", paymentId: "pay_nope", created: 1762300400 })).status, 404);
});
EOF
